import{_ as t,c as a,o as r,ag as i}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1791309864000}'),o={name:"guide/introduction.md"};function n(l,e,d,s,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="about-nplyr" tabindex="-1">About nPlyr <a class="header-anchor" href="#about-nplyr" aria-label="Permalink to &quot;About nPlyr&quot;">​</a></h2><p><strong>nPlyr</strong> is a native video player for <strong>macOS</strong> and <strong>iOS / iPadOS</strong>. It is built on Apple&#39;s <a href="https://developer.apple.com/av-foundation/" target="_blank" rel="noreferrer">AVFoundation</a> (<code>AVPlayer</code>) — there is <strong>no external binary</strong> inside the app. On top of the player it adds two things that make it more than a plain viewer:</p><ul><li>a <strong>built-in media sniffer</strong> (a Chrome-style multi-tab browser that captures direct video links from any web page), and</li><li>a <strong>hikerView-compatible mini-program runtime</strong> that runs community rules so the app can browse and parse third-party video sources.</li></ul><p>This combination is sometimes called a <em>&quot;player + sniffer + mini-program runtime&quot;</em> in one.</p><h2 id="the-three-pillars" tabindex="-1">The three pillars <a class="header-anchor" href="#the-three-pillars" aria-label="Permalink to &quot;The three pillars&quot;">​</a></h2><h3 id="_1-native-player" tabindex="-1">1. Native Player <a class="header-anchor" href="#_1-native-player" aria-label="Permalink to &quot;1. Native Player&quot;">​</a></h3><p>A single playback core shared by macOS and iOS. It plays HLS (<code>m3u8</code>), <code>MP4</code>, <code>MOV</code>, <code>M4V</code>, <code>FLV</code>, <code>TS</code> and any container <code>AVPlayer</code> can decode, with:</p><ul><li>subtitles (external <code>.srt</code> / <code>.vtt</code> / embedded),</li><li>multiple audio tracks,</li><li>playback speed control,</li><li>Picture-in-Picture,</li><li>AirPlay and (on macOS) DLNA rendering.</li></ul><p>See <a href="/guide/player.html">Player</a>.</p><h3 id="_2-sniffer-browser" tabindex="-1">2. Sniffer Browser <a class="header-anchor" href="#_2-sniffer-browser" aria-label="Permalink to &quot;2. Sniffer Browser&quot;">​</a></h3><p>nPlyr embeds a real <code>WKWebView</code> with multiple Chrome-style tabs. A media-detection script is injected into every page; when the page requests <code>m3u8</code> / <code>mp4</code> / <code>flv</code> / <code>ts</code> media, the link — together with its request headers — appears in a results drawer you can send straight to the player or downloader.</p><p>See <a href="/guide/browser.html">Browser &amp; Sniffer</a>.</p><h3 id="_3-mini-program-runtime" tabindex="-1">3. Mini-Program Runtime <a class="header-anchor" href="#_3-mini-program-runtime" aria-label="Permalink to &quot;3. Mini-Program Runtime&quot;">​</a></h3><p>nPlyr reimplements the <strong>hikerView mini-program contract</strong> natively:</p><ul><li>the rule DSL (<code>pdfh</code> / <code>pdfa</code> / <code>pd</code> selectors, <code>setResult</code>, <code>lazyRule</code>, <code>$.rule</code>, …),</li><li>the <code>fy_bridge_app</code> (<code>fba</code>) JavaScript bridge that rules use to call host features (play, fetch, parse, store variables),</li><li>the <code>hiker://</code> pseudo-protocol routing.</li></ul><p>Existing hikerView community rules and mini-programs can therefore run inside nPlyr. Because the original engine is Android/Java (Rhino), <strong>some Java-specific behavior is not fully compatible</strong> — this is documented in detail on the <a href="/guide/miniapp-compatibility.html">Compatibility</a> page.</p><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Minimum version</th><th>Notes</th></tr></thead><tbody><tr><td>macOS</td><td>macOS 14 Sonoma</td><td>Apple Silicon (M-series) optimized; Intel supported</td></tr><tr><td>iOS</td><td>iOS 16</td><td>iPhone</td></tr><tr><td>iPadOS</td><td>iPadOS 16</td><td>iPad</td></tr></tbody></table><ul><li><strong>Memory</strong>: 4 GB RAM minimum, 8 GB recommended for large HLS playlists.</li><li><strong>Storage</strong>: ~60 MB for installation, plus space for downloaded media.</li><li><strong>Network</strong>: required for streaming, sniffing and mini-program sources.</li></ul><h2 id="supported-languages" tabindex="-1">Supported Languages <a class="header-anchor" href="#supported-languages" aria-label="Permalink to &quot;Supported Languages&quot;">​</a></h2><p>The app UI is translated into <strong>25 languages</strong> and follows the system language on first launch. The documentation site is available in English, 简体中文, 繁體中文, 日本語, Deutsch, Español and Français.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><ol><li><a href="/guide/installation.html">Install</a> nPlyr on your Mac or iPhone.</li><li>Learn the <a href="/guide/player.html">Player</a> basics.</li><li>Capture a stream with the <a href="/guide/browser.html">Browser &amp; Sniffer</a>.</li><li>Explore community sources through <a href="/guide/miniapps.html">Mini-Programs</a>.</li></ol>',24)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
